"""
title: Tavily Web Search
description: Search the web with the Tavily API and return titles, URLs and content snippets.
requirements: requests
version: 0.1.0
"""

import json
import os

import requests
from pydantic import BaseModel, Field


class Tools:
    class Valves(BaseModel):
        TAVILY_API_KEY: str = Field(
            default="",
            description="Tavily API key. Leave empty to use the TAVILY_API_KEY environment variable.",
        )
        MAX_RESULTS: int = Field(
            default=5, ge=1, le=20, description="Number of results to return."
        )
        SEARCH_DEPTH: str = Field(
            default="basic",
            description="'basic' (1 credit per search) or 'advanced' (2 credits).",
        )

    def __init__(self):
        self.valves = self.Valves()

    def search_web(self, query: str) -> str:
        """
        Search the web for current information and return the top results.
        :param query: The search query.
        :return: JSON list of results, each with 'title', 'url' and 'content'.
        """
        if not query or not query.strip():
            return json.dumps({"error": "No search query was provided."})

        api_key = self.valves.TAVILY_API_KEY or os.environ.get("TAVILY_API_KEY", "")
        if not api_key:
            return json.dumps(
                {
                    "error": "No Tavily API key configured. Set the TAVILY_API_KEY valve or environment variable."
                }
            )

        try:
            response = requests.post(
                "https://api.tavily.com/search",
                headers={"Authorization": f"Bearer {api_key}"},
                json={
                    "query": query,
                    "max_results": self.valves.MAX_RESULTS,
                    "search_depth": self.valves.SEARCH_DEPTH,
                },
                timeout=30,
            )
            response.raise_for_status()
            results = response.json().get("results", [])
        except requests.HTTPError as e:
            return json.dumps(
                {"error": f"Tavily returned HTTP {e.response.status_code}."}
            )
        except (requests.RequestException, ValueError) as e:
            return json.dumps({"error": f"Search failed: {type(e).__name__}"})

        return json.dumps(
            [
                {
                    "title": r.get("title", ""),
                    "url": r.get("url", ""),
                    "content": r.get("content", ""),
                }
                for r in results
            ]
        )
